package org.json;public class JSONArray {private final Object[] values;public JSONArray(Object...v){values=v;}public String toString(){StringBuilder b=new StringBuilder("[");for(Object v:values){if(b.length()>1)b.append(',');b.append(JSONObject.encode(v));}return b.append(']').toString();} public int length(){return values.length;}public JSONObject optJSONObject(int i){return i>=0&&i<values.length&&values[i] instanceof JSONObject?(JSONObject)values[i]:null;}public JSONArray optJSONArray(int i){return i>=0&&i<values.length&&values[i] instanceof JSONArray?(JSONArray)values[i]:null;} public double optDouble(int i,double fallback){return i>=0&&i<values.length&&values[i] instanceof Number?((Number)values[i]).doubleValue():fallback;} public double optDouble(int i){return i>=0&&i<values.length&&values[i] instanceof Number?((Number)values[i]).doubleValue():0;} }
